pm.test("Start session returns 200 and sets position 1", () => {
  pm.response.to.have.status(200);
  const data = pm.response.json().data;
  pm.expect(data.status).to.eql("RUNNING");
  pm.expect(data.current_position).to.eql(1);
});

pm.test("Current question returns 200 without is_correct", () => {
  pm.response.to.have.status(200);
  const q = pm.response.json();
  pm.expect(q.position).to.eql(1);
  pm.expect(q.choices).to.be.an("array").with.lengthOf(2);
  q.choices.forEach(c => pm.expect(c).to.not.have.property("is_correct"));
});

pm.test("Player 1 Q1 answer returns 201 with points", () => {
  pm.response.to.have.status(201);
  const ans = pm.response.json();
  pm.expect(ans.is_correct).to.eql(true);
  pm.expect(ans.points_earned).to.be.above(0);
});

pm.test("Player 2 Q1 wrong answer returns 201 with 0 points", () => {
  pm.response.to.have.status(201);
  const ans = pm.response.json();
  pm.expect(ans.is_correct).to.eql(false);
  pm.expect(ans.points_earned).to.eql(0);
});

pm.test("Leaderboard returns 200 with ranked players", () => {
  pm.response.to.have.status(200);
  const body = pm.response.json();
  pm.expect(body.leaderboard).to.be.an("array").with.lengthOf(2);
  pm.expect(body.leaderboard[0].rank).to.eql(1);
  pm.expect(body.leaderboard[0].nickname).to.eql("StarRunner");
  pm.expect(body.leaderboard[1].rank).to.eql(2);
});

pm.test("Hub /results lists the newly played game with completed players", () => {
  pm.response.to.have.status(200);
  const body = pm.response.json();
  const code = pm.collectionVariables.get("gameCode");
  const played = body.results.find(r => r.session_code === code);
  pm.expect(played).to.not.be.undefined;
  pm.expect(played.players.some(p => p.completed === true)).to.eql(true);
});
